import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 환경설정에 연령구간 값이 없으면 이 구간 기준(일)을 쓴다.
const DEFAULT_BOUNDS = [30, 60, 90];
// 가정: 연령구간은 system_setting 분류 '연령구간'의 설정 값(일수 숫자)이다.
const AGING_CATEGORY = '연령구간';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 가정: 채권 라인은 계정 구분이 '자산'인 라인의 차변 금액, 채무 라인은 '부채'인 라인의 대변 금액이다.
const LINE_FROM = `
  FROM journal_entry_line l
  JOIN journal_entry e ON e.journal_entry_id = l.journal_entry_id
  JOIN account_subject a ON a.account_subject_id = l.account_subject_id
  WHERE l.partner_id IS NOT NULL
    AND e.entry_date <= CAST(:baseDate AS date)
    AND (CAST(:partnerId AS bigint) IS NULL OR l.partner_id = CAST(:partnerId AS bigint))
    AND (CAST(:accountSubjectId AS bigint) IS NULL OR l.account_subject_id = CAST(:accountSubjectId AS bigint))`;

const SETTLED_RECEIVABLE = `COALESCE((SELECT SUM(s.settlement_amount) FROM journal_settlement s WHERE s.receivable_line_id = l.journal_entry_line_id), 0)`;
const SETTLED_PAYABLE = `COALESCE((SELECT SUM(s.settlement_amount) FROM journal_settlement s WHERE s.payable_line_id = l.journal_entry_line_id), 0)`;

interface ListQuery {
  baseDate: string;
  partnerId: number | null;
  accountSubjectId: number | null;
  page: number;
  size: number;
}

function idOf(value: unknown, label: string): number | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label}는 숫자여야 합니다.`);
  }
  return n;
}

function parseQuery(q: Record<string, unknown>): ListQuery {
  const baseDate = typeof q['baseDate'] === 'string' ? q['baseDate'] : '';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '기준일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  const rawPage = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
  const rawSize = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
  if (!Number.isInteger(rawPage) || rawPage < 0 || !Number.isInteger(rawSize) || rawSize < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 쪽 크기가 올바르지 않습니다.');
  }
  return {
    baseDate,
    partnerId: idOf(q['partnerId'], '거래처 ID'),
    accountSubjectId: idOf(q['accountSubjectId'], '계정과목 ID'),
    page: rawPage,
    size: Math.min(rawSize, MAX_SIZE),
  };
}

function bucketLabel(bounds: number[], index: number): string {
  if (index >= bounds.length) {
    return `${bounds[bounds.length - 1]}일 초과`;
  }
  if (index === 0) {
    return `0~${bounds[0]}일`;
  }
  return `${bounds[index - 1] + 1}~${bounds[index]}일`;
}

function bucketIndex(bounds: number[], days: number): number {
  for (let i = 0; i < bounds.length; i += 1) {
    if (days <= bounds[i]) {
      return i;
    }
  }
  return bounds.length;
}

@Controller('api/v1')
export class FnSfr00808Controller {
  @Get('/receivable-aging')
  async listReceivableAging(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const q = parseQuery(checks.queryOf(req.query));
    return transaction(async (db) => {
      const settings = await db.query(
        `SELECT setting_value AS "value" FROM system_setting WHERE category = :category AND setting_value ~ '^[0-9]+$'`,
        { category: AGING_CATEGORY },
      );
      const configured = Array.from(new Set(settings.map((r: any) => Number(r.value))))
        .filter((n) => Number.isFinite(n))
        .sort((x, y) => x - y);
      const bounds = configured.length > 0 ? configured : DEFAULT_BOUNDS;
      const lines = await db.query(
        `SELECT l.partner_id AS "partnerId",
          (CAST(:baseDate AS date) - e.entry_date) AS "days",
          (l.debit_amount - ${SETTLED_RECEIVABLE}) AS "balance"
        ${LINE_FROM}
          AND a.category = '자산'
          AND l.debit_amount > 0`,
        { baseDate: q.baseDate, partnerId: q.partnerId, accountSubjectId: q.accountSubjectId },
      );
      const sums = new Map<string, { partnerId: number; index: number; balance: number }>();
      for (const line of lines as any[]) {
        const balance = Number(line.balance);
        if (balance <= 0) {
          continue;
        }
        const index = bucketIndex(bounds, Number(line.days));
        const key = `${line.partnerId}|${index}`;
        const found = sums.get(key);
        if (found) {
          found.balance += balance;
        } else {
          sums.set(key, { partnerId: Number(line.partnerId), index, balance });
        }
      }
      const all = Array.from(sums.values()).sort((x, y) => x.partnerId - y.partnerId || x.index - y.index);
      const items = all
        .slice(q.page * q.size, q.page * q.size + q.size)
        .map((r) => ({ partnerId: r.partnerId, bucket: bucketLabel(bounds, r.index), balance: Math.round(r.balance * 100) / 100 }));
      return { items, page: q.page, size: q.size, total: all.length };
    });
  }

  @Get('/partner-balances')
  async listPartnerBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const q = parseQuery(checks.queryOf(req.query));
    return transaction(async (db) => {
      const base = `WITH x AS (
        SELECT l.partner_id AS partner_id, a.category AS category,
          CASE WHEN a.category = '자산' THEN l.debit_amount - ${SETTLED_RECEIVABLE}
               WHEN a.category = '부채' THEN l.credit_amount - ${SETTLED_PAYABLE}
               ELSE 0 END AS bal
        ${LINE_FROM}
          AND a.category IN ('자산', '부채')
      )`;
      const params = { baseDate: q.baseDate, partnerId: q.partnerId, accountSubjectId: q.accountSubjectId };
      const rows = await db.query(
        `${base}
        SELECT partner_id AS "partnerId",
          CAST(COALESCE(SUM(CASE WHEN category = '자산' THEN bal END), 0) AS numeric) AS "receivableBalance",
          CAST(COALESCE(SUM(CASE WHEN category = '부채' THEN bal END), 0) AS numeric) AS "payableBalance"
        FROM x
        GROUP BY partner_id
        ORDER BY partner_id
        LIMIT :limit OFFSET :offset`,
        { ...params, limit: q.size, offset: q.page * q.size },
      );
      const counted = await db.query(
        `${base}
        SELECT COUNT(*) AS "total" FROM (SELECT partner_id FROM x GROUP BY partner_id) t`,
        params,
      );
      const total = Number(counted[0]?.total ?? 0);
      const items = (rows as any[]).map((r) => ({
        partnerId: Number(r.partnerId),
        receivableBalance: Number(r.receivableBalance),
        payableBalance: Number(r.payableBalance),
      }));
      return { items, page: q.page, size: q.size, total };
    });
  }
}

