import { useState } from 'react';
import {
  call,
  useData,
  Band,
  DataTable,
  DateInput,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  RefName,
  TextInput,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

type View = 'aging' | 'balances';

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

export default function FnSfr00808Page({ role, notify }: PageProps) {
  const [view, setView] = useState<View>('aging');
  const [baseDate, setBaseDate] = useState<string>(today());
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [accountSubjectId, setAccountSubjectId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({ baseDate: today() });
  const [page, setPage] = useState(0);
  const [settling, setSettling] = useState(false);
  const [form, setForm] = useState<Row>({});

  const path = view === 'aging' ? '/receivable-aging' : '/partner-balances';
  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', path, role, undefined, { ...applied, page }),
    [path, applied, page],
  );

  const search = () => {
    if (!baseDate) {
      notify('기준일자를 입력해 주세요.');
      return;
    }
    setPage(0);
    setApplied({ baseDate, partnerId, accountSubjectId });
  };

  const reset = () => {
    setBaseDate(today());
    setPartnerId('');
    setAccountSubjectId('');
    setPage(0);
    setApplied({ baseDate: today() });
  };

  const change = (next: View) => {
    setView(next);
    setPage(0);
  };

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const partnerCell = {
    key: 'partnerId',
    label: '거래처',
    render: (row: Row) => <RefName table="partner" role={role} value={row.partnerId} />,
  };

  const agingColumns = [
    partnerCell,
    { key: 'bucket', label: '연령 구간' },
    { key: 'balance', label: '구간별 채권 잔액', render: (row: Row) => <Num value={row.balance} /> },
  ];

  const balanceColumns = [
    partnerCell,
    { key: 'receivableBalance', label: '채권 잔액', render: (row: Row) => <Num value={row.receivableBalance} /> },
    { key: 'payableBalance', label: '채무 잔액', render: (row: Row) => <Num value={row.payableBalance} /> },
  ];

  const submitSettlement = async () => {
    const required: [string, string][] = [
      ['bankTransactionId', '반제할 예외 거래내역 ID'],
      ['receivableLineId', '채권 분개라인'],
      ['payableLineId', '채무 분개라인'],
      ['partnerId', '거래처'],
      ['settlementAmount', '반제·상계 금액'],
    ];
    for (const [key, label] of required) {
      if (form[key] === undefined || form[key] === '') {
        throw new Error(`${label}을(를) 입력해 주세요.`);
      }
    }
    if (typeof form.settlementAmount !== 'number' || form.settlementAmount <= 0) {
      throw new Error('반제·상계 금액은 0보다 큰 숫자여야 합니다.');
    }
    await call('POST', '/journal-settlements', role, form);
    notify('상계 처리를 했습니다.');
    setSettling(false);
    setForm({});
    reload();
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>채권·채무 관리</h2>
        <div>
          <button className={view === 'aging' ? '' : 'ghost'} onClick={() => change('aging')}>
            채권 연령분석
          </button>
          <button className={view === 'balances' ? '' : 'ghost'} onClick={() => change('balances')}>
            채권·채무 잔액
          </button>
        </div>
        <Filters onSearch={search} onReset={reset}>
          <Field label={view === 'aging' ? '연령분석 기준일' : '잔액 기준일'} required>
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label="거래처 ID">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체 거래처" />
          </Field>
          <Field label="계정과목 ID">
            <LookupSelect
              table="account_subject"
              role={role}
              value={accountSubjectId}
              onChange={setAccountSubjectId}
              placeholder="전체 계정과목"
            />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={() => setSettling(true)}>상계 처리</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={view === 'aging' ? agingColumns : balanceColumns}
          rows={data?.items ?? []}
          empty={loading ? '불러오는 중입니다.' : '조회 조건에 맞는 채권·채무 내역이 없습니다. 기준일자를 바꿔 다시 조회해 주세요.'}
        />
        <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {settling ? (
        <Drawer title="채권·채무 상계 처리" onClose={() => setSettling(false)}>
          <Form
            onSubmit={submitSettlement}
            submit="상계 처리"
            danger
            note="상계 처리를 하면 되돌릴 수 없고, 채권과 채무의 잔액이 함께 줄어듭니다. 같은 거래처의 채권과 채무만 상계할 수 있습니다."
          >
            <Field label="반제할 예외 거래내역 ID" required>
              <NumberInput value={form.bankTransactionId} onChange={(v) => set('bankTransactionId', v)} />
            </Field>
            <Field label="거래처 ID" required>
              <LookupSelect table="partner" role={role} value={form.partnerId} onChange={(v) => set('partnerId', v)} />
            </Field>
            <Field label="채권 분개라인 ID" required>
              <LookupSelect
                table="journal_entry_line"
                role={role}
                value={form.receivableLineId}
                onChange={(v) => set('receivableLineId', v)}
              />
            </Field>
            <Field label="채무 분개라인 ID" required>
              <LookupSelect
                table="journal_entry_line"
                role={role}
                value={form.payableLineId}
                onChange={(v) => set('payableLineId', v)}
              />
            </Field>
            <Field label="반제·상계 금액" required>
              <NumberInput value={form.settlementAmount} onChange={(v) => set('settlementAmount', v)} />
            </Field>
            <Field label="처리 내용" wide>
              <TextInput multiline value={form.memo} onChange={(v) => set('memo', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
